# Comma-separated peer CA sources (IP, host, or full URL).
# Bare values are fetched as http://<peer>/ca.crt
# Example: 10.0.0.5,10.0.0.6,http://10.0.0.7/ca.crt
CA_PEERS={{ca_peers}}
# Seconds between refresh passes (default 60).
CA_REFRESH_SECONDS={{ca_refresh_seconds}}

files.files/Caddyfile:
{
  auto_https disable_redirects
}

:80 {
    handle /ca.crt {
        root * /data/caddy/pki/authorities/local
        rewrite * /root.crt
        header Content-Type application/x-pem-file
        file_server
    }
    handle {
        respond "Elemento Caddy CA export. GET /ca.crt" 200
    }
}

__HERMES_DOMAIN__ {
    tls internal

    # OpenAI-compatible API + health (gateway :8642)
    handle /v1* {
        reverse_proxy hermes:8642 {
            header_up Host {host}
            header_up X-Forwarded-For {remote_host}
            header_up X-Real-IP {remote_host}
            header_up X-Forwarded-Proto {scheme}
        }
    }
    handle /health {
        reverse_proxy hermes:8642 {
            header_up Host {host}
            header_up X-Forwarded-For {remote_host}
            header_up X-Real-IP {remote_host}
            header_up X-Forwarded-Proto {scheme}
        }
    }

    # Web dashboard (gateway :9119) — Hermes enforces basic auth
    handle {
        reverse_proxy hermes:9119 {
            header_up Host {host}
            header_up X-Forwarded-For {remote_host}
            header_up X-Real-IP {remote_host}
            header_up X-Forwarded-Proto {scheme}
        }
    }
}

