#!/bin/sh
# Run on the VM, e.g.: multipass exec <vm> -- /opt/n8n/healthcheck.sh
set -eu

fail() {
  echo "FAIL: $*" >&2
  exit 1
}

ok() {
  echo "OK: $*"
}

command -v docker >/dev/null 2>&1 || fail "docker not installed"
command -v curl >/dev/null 2>&1 || fail "curl not installed"

docker info >/dev/null 2>&1 || fail "docker daemon not reachable"

state=$(docker inspect -f '{{.State.Running}}' n8n 2>/dev/null || true)
[ "$state" = "true" ] || fail "n8n container is not running"

code=$(curl -sS -o /dev/null -w "%{http_code}" --max-time 5 "http://127.0.0.1:5678/" || true)
case "$code" in
  2??|3??) ok "n8n HTTP responded with $code on :5678" ;;
  *) fail "n8n HTTP check failed (status=${code:-unreachable})" ;;
esac

ok "n8n is healthy"

