files.files/configure-openclaw.sh:
#!/bin/sh
set -eu

ENV_FILE=/opt/openclaw/openclaw.env
CONFIG_DIR=/root/.openclaw
CONFIG_FILE="${CONFIG_DIR}/openclaw.json"

if [ -f "$ENV_FILE" ]; then
  # shellcheck disable=SC1090
  . "$ENV_FILE"
fi

TOKEN="${OPENCLAW_TOKEN:-}"
PORT="${OPENCLAW_GATEWAY_PORT:-18789}"
DOMAIN="${OPENCLAW_CADDY_DOMAIN:-}"
ORIGINS="${OPENCLAW_ALLOWED_ORIGINS:-}"

pick_lan_ip() {
  for ip in $(hostname -I); do
    case "$ip" in
      *:*|127.*|172.17.*) continue ;;
    esac
    case "$ip" in
      10.*|192.168.*|172.1[6-9].*|172.2[0-9].*|172.3[0-1].*)
        echo "$ip"
        return 0
        ;;
    esac
  done
  for ip in $(hostname -I); do
    case "$ip" in
      *:*|127.*) continue ;;
      *.*.*.*)
        echo "$ip"
        return 0
        ;;
    esac
  done
  echo "127.0.0.1"
}

if [ -z "$DOMAIN" ] || echo "$DOMAIN" | grep -q '{\|:'; then
  DOMAIN="$(pick_lan_ip).nip.io"
fi

if [ -z "$ORIGINS" ] || echo "$ORIGINS" | grep -q '{'; then
  ORIGINS="https://${DOMAIN},wss://${DOMAIN}"
fi

if [ -z "$TOKEN" ] || echo "$TOKEN" | grep -q '{'; then
  echo "OPENCLAW_TOKEN is required (pass -v token=... when rendering)" >&2
  exit 1
fi

mkdir -p "${CONFIG_DIR}/workspace"

# Build a JSON array from the comma-separated origin list.
origins_json="["
first=1
OLDIFS=$IFS
IFS=,
for origin in $ORIGINS; do
  origin=$(echo "$origin" | tr -d '[:space:]')
  [ -n "$origin" ] || continue
  if [ "$first" -eq 1 ]; then
    first=0
  else
    origins_json="${origins_json},"
  fi
  origins_json="${origins_json}
      \"${origin}\""
done
IFS=$OLDIFS
origins_json="${origins_json}
    ]"

cat > "$CONFIG_FILE" <<EOF
{
  "gateway": {
    "trustedProxies": [
      "127.0.0.1"
    ],
    "bind": "loopback",
    "port": ${PORT},
    "auth": {
      "mode": "token",
      "token": "${TOKEN}"
    },
    "controlUi": {
      "allowedOrigins": ${origins_json},
      "dangerouslyDisableDeviceAuth": true
    },
    "mode": "local"
  },
  "agents": {
    "defaults": {
      "workspace": "/root/.openclaw/workspace",
      "models": {
        "openai/gpt-5.5": {
          "alias": "GPT"
        }
      },
      "model": {
        "primary": "openai/gpt-5.5"
      }
    }
  },
  "session": {
    "dmScope": "per-channel-peer"
  },
  "tools": {
    "profile": "coding"
  },
  "auth": {
    "profiles": {
      "openai:default": {
        "provider": "openai",
        "mode": "api_key"
      }
    }
  },
  "plugins": {
    "entries": {
      "whatsapp": {
        "enabled": true
      },
      "openai": {
        "enabled": true
      }
    }
  }
}
EOF

